package com.reg21meme.dross.boss.huntsman.village;

import com.reg21meme.dross.Dross;
import java.util.List;
import net.minecraft.resources.ResourceLocation;

/**
 * The hunter village designs and the Huntsman's lodge (generated by tools/huntsman/villages.py; don't edit by hand).
 * Each is a structure template {@code dross:hunter_village/<id>}: {@code width} x {@code depth} blocks and
 * {@code layers} tall, its ground at layer {@code groundLayer} (the layers under it reach into the ground), its
 * middle the village's middle, its way in at the south (+Z) edge. The lodge has number 0.
 */
public final class HunterVillageDesigns
{
    private HunterVillageDesigns() {}

    public record Design(int number, String id, String name, String mood, int width, int depth, int layers,
                         int groundLayer, int height, int igloos)
    {
        public ResourceLocation template()
        {
            return new ResourceLocation(Dross.MODID, "hunter_village/" + id);
        }

        public boolean isLodge()
        {
            return number == 0;
        }
    }

    /** The ten villages (numbers 1-10, in order), then the lodge. */
    public static final List<Design> ALL = List.of(
            new Design(1, "hearthfire_ring", "Hearthfire Ring", "seven igloos round a great fire, every door facing it", 55, 55, 18, 2, 7, 7),
            new Design(2, "whalebone_way", "Whalebone Way", "a street under great arches of bone, a beast's skull at its end", 41, 63, 20, 2, 12, 6),
            new Design(3, "stockade_camp", "Stockade Camp", "six igloos inside a log palisade with a gatehouse and an archery yard", 51, 51, 20, 2, 10, 6),
            new Design(4, "the_warren", "The Warren", "a great hall dome and six igloos joined to it by covered passages", 53, 53, 20, 2, 8, 7),
            new Design(5, "sunken_hollow", "Sunken Hollow", "six igloos sunk into the rim of a hollow dug out of the snow", 47, 47, 18, 5, 6, 6),
            new Design(6, "windbreak_crescent", "Windbreak Crescent", "seven igloos sheltering behind a great curved wall of snow", 61, 49, 18, 2, 8, 7),
            new Design(7, "antler_camp", "Antler Camp", "two clusters of igloos round a trophy ground of antlers, skulls and hides", 57, 55, 18, 2, 7, 6),
            new Design(8, "ice_lantern_way", "Ice Lantern Way", "glittering igloos of packed ice along a winding lantern-lit path", 45, 63, 18, 2, 9, 7),
            new Design(9, "snow_angel_circle", "Snow Angel Circle", "igloos round a ring of stone figures and a statue of the Snow Angel", 57, 57, 20, 2, 14, 7),
            new Design(10, "smokehouse_camp", "Smokehouse Camp", "a working camp: drying racks, a stone smokehouse, a pen and an ice cellar", 57, 55, 18, 6, 10, 6),
            new Design(0, "huntsman_lodge", "The Huntsman's Lodge", "his great lodge, an armoury and a stable for the Alpha Moose", 53, 49, 24, 2, 15, 2));

    public static List<Design> villages()
    {
        return ALL.stream().filter(d -> !d.isLodge()).toList();
    }

    public static Design lodge()
    {
        return ALL.stream().filter(Design::isLodge).findFirst().orElseThrow();
    }
}
